fn flushTakeContiguousRun(
    allocator: std.mem.Allocator,
    out_chunks: *std.ArrayList(ArrayRef),
    chunks: ChunkedArray,
    chunk_index: usize,
    run_start_local: usize,
    run_len: usize,
) KernelError!void {
    if (run_len == 0) return;
    const source = chunks.chunk(chunk_index).*;
